css:
/* A. 深い弧: 上の色面の下辺を巨大な白円でえぐる */
.hero{position:relative; overflow:hidden; background:#1d5137}
.hero::after{content:''; position:absolute; left:-12%; bottom:-72%;
  width:124%; aspect-ratio:1; border-radius:50%; background:#fbfaf7}

/* B. 扁平弧: 次セクション側を持ち上げる（縦半径を幅よりはるかに小さく） */
.next{background:#f6f5fa; margin-top:-40px;
  border-radius:50% 50% 0 0 / 40px 40px 0 0}

/* C. 非対称にする: left/top を左右非対称にずらす */
.sec{background:#f4f4f2; position:relative; overflow:hidden}
.sec::before{content:''; position:absolute; left:-34%; top:-150%;
  width:170%; aspect-ratio:1; border-radius:50%; background:#fff}
